{
  "steps": [
    {
      "id": "step-1",
      "goal": "Open all unread invoice emails in the AP mailbox and save every invoice attachment to the working folder before any ERP action.",
      "allowed_tools": [
        "mail.list",
        "mail.read",
        "mail.mark_read",
        "files.write"
      ],
      "done_criterion": "All unread invoice emails in the AP mailbox have been opened, every invoice attachment has been saved to the working folder, and the emails have been marked read; no ERP tools have been used yet."
    },
    {
      "id": "step-2",
      "goal": "Extract invoice fields from each saved PDF and record missing or unreadable fields as open questions without guessing.",
      "allowed_tools": [
        "files.list",
        "files.read",
        "files.write"
      ],
      "done_criterion": "For every invoice PDF in the working folder, vendor, invoice number, amount, purchase order, goods receipt, invoice date, and payment terms have been extracted or recorded as open questions; no missing or unreadable value has been guessed."
    },
    {
      "id": "step-3",
      "goal": "Verify in LedgerLite that each vendor exists, is not blocked, and that the invoice matches its purchase order and goods receipt.",
      "allowed_tools": [
        "erp.list_vendors",
        "erp.get_vendor",
        "erp.list_purchase_orders",
        "erp.get_purchase_order",
        "erp.get_goods_receipt"
      ],
      "done_criterion": "Each invoice vendor has been checked in LedgerLite and exists, is not blocked, and the referenced purchase order and goods receipt exist and match the invoice references."
    },
    {
      "id": "step-4",
      "goal": "Validate invoice amount against the purchase order and identify duplicate invoices; record mismatches and duplicates as exceptions.",
      "allowed_tools": [
        "erp.list_invoices",
        "erp.get_invoice",
        "erp.get_purchase_order",
        "files.write"
      ],
      "done_criterion": "Every non-duplicate invoice amount equals the corresponding purchase order amount; any duplicate invoice or amount mismatch has been recorded as an exception and will not be filed."
    },
    {
      "id": "step-5",
      "goal": "File validated invoices in LedgerLite against the correct purchase order and goods receipt.",
      "allowed_tools": [
        "erp.file_invoice"
      ],
      "done_criterion": "All validated, non-exception invoices have been filed in LedgerLite against the correct purchase order and goods receipt; duplicate or mismatched invoices have not been filed."
    },
    {
      "id": "step-6",
      "goal": "Prepare payment schedules in USD through LedgerLite, applying spend-limit approval holds and blocking invalid vendors.",
      "allowed_tools": [
        "erp.schedule_payment"
      ],
      "done_criterion": "Payment schedules have been prepared only in USD for filed invoices, with no split payments, no payments for blocked vendors, and any payment above 10,000.00 USD prepared but held for human approval."
    },
    {
      "id": "step-7",
      "goal": "Move source PDFs and scans to the processed folder and record their archived location.",
      "allowed_tools": [
        "files.move",
        "files.archive",
        "files.write"
      ],
      "done_criterion": "All source invoice PDFs and scans have been moved to the processed folder and their archived locations have been recorded."
    },
    {
      "id": "step-8",
      "goal": "Verify against LedgerLite and the filesystem that each filed invoice exists with the correct amount and status, and that source documents are archived.",
      "allowed_tools": [
        "erp.list_invoices",
        "erp.get_invoice",
        "files.list"
      ],
      "done_criterion": "LedgerLite shows an invoice record with the correct amount and status for each filed invoice, and the filesystem confirms the corresponding source document is archived."
    },
    {
      "id": "step-9",
      "goal": "Report and escalate any exception or unmet success criterion to the AP owner.",
      "allowed_tools": [
        "files.write"
      ],
      "done_criterion": "An exception report listing all exceptions, open questions, and unmet success criteria has been written and saved for escalation to the AP owner."
    }
  ]
}
